// Normalize Telegram message
const body = $input.first().json.body;
const message = body.message || body.edited_message;

if (!message || !message.text) {
  return [{ json: { skip: true } }];
}

return [{
  json: {
    channel: 'Telegram',
    chat_id: String(message.chat.id),
    user_text: message.text,
    user_name: message.from.first_name || '',
    username: message.from.username ? '@' + message.from.username : '',
    timestamp: new Date().toISOString()
  }
}];

// Normalize WhatsApp message (Meta Cloud API)
const body = $input.first().json.body;

try {
  const entry = body.entry?.[0];
  const changes = entry?.changes?.[0];
  const value = changes?.value;
  const messages = value?.messages;

  if (!messages || messages.length === 0) {
    return [{ json: { skip: true } }];
  }

  const msg = messages[0];
  if (msg.type !== 'text') {
    return [{ json: { skip: true } }];
  }

  const contact = value.contacts?.[0];

  return [{
    json: {
      channel: 'WhatsApp',
      chat_id: msg.from,
      user_text: msg.text.body,
      user_name: contact?.profile?.name || '',
      username: msg.from,
      timestamp: new Date().toISOString()
    }
  }];
} catch(e) {
  return [{ json: { skip: true } }];
}

// Build the request to Claude API directly
const ctx = $('Compile Message Context').item.json;

// Build the messages array from Google Sheets history
// history already includes the current user message (added in Build Context)
const messages = ctx.conversation_history || [];

// Make sure the first message is from 'user' (Claude requires user first)
const cleanMessages = messages.filter(function(m) {
  return m.role === 'user' || m.role === 'assistant';
});

// If history starts with 'assistant', remove it (shouldn't happen)
while (cleanMessages.length > 0 && cleanMessages[0].role === 'assistant') {
  cleanMessages.shift();
}

return [{
  json: {
    channel: ctx.channel,
    chat_id: ctx.chat_id,
    user_name: ctx.user_name,
    username: ctx.username,
    timestamp: ctx.timestamp,
    conversation_history: ctx.conversation_history,
    is_new_lead: ctx.is_new_lead,
    disclaimer_shown: ctx.disclaimer_shown,
    existing_name: ctx.existing_name,
    existing_product: ctx.existing_product,
    existing_status: ctx.existing_status,
    claude_request: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1024,
      system: ctx.system_prompt,
      messages: cleanMessages
    }
  }
}];

// Extract Claude's reply and parse the control tags
const claudeResponse = $json;
const prevCtx = $('Setup Request for Claude').item.json;

// Extract Claude's response text
let aiResponse = '';
if (claudeResponse.content && claudeResponse.content.length > 0) {
  aiResponse = claudeResponse.content
    .filter(function(b) { return b.type === 'text'; })
    .map(function(b) { return b.text; })
    .join('');
}

if (!aiResponse) {
  aiResponse = 'Sorry, something went wrong on our end. Please try again or contact us directly at [YOUR_SUPPORT_EMAIL]';
}

// Parse control tags
const hasRecord = aiResponse.includes('[RECORD:');
const hasUpdate = aiResponse.includes('[UPDATE:');
const hasHot = aiResponse.includes('[HOT_LEAD]');
const hasWarm = aiResponse.includes('[WARM_LEAD]');
const hasCold = aiResponse.includes('[COLD_LEAD]');
const hasManager = aiResponse.includes('[MANAGER_REQUEST]');

let leadStatus = prevCtx.existing_status || 'In progress';
if (hasHot) leadStatus = 'HOT';
else if (hasWarm) leadStatus = 'WARM';
else if (hasCold) leadStatus = 'COLD';
else if (hasManager) leadStatus = 'Manager requested';

// Strip tags from the visible reply
const cleanResponse = aiResponse
  .replace(/\[RECORD:[^\]]*\]/g, '')
  .replace(/\[UPDATE:[^\]]*\]/g, '')
  .replace(/\[HOT_LEAD\]/g, '')
  .replace(/\[WARM_LEAD\]/g, '')
  .replace(/\[COLD_LEAD\]/g, '')
  .replace(/\[MANAGER_REQUEST\]/g, '')
  .replace(/\[LEAD_SOURCE:[^\]]*\]/g, '')
  .trim();

// Update history
const history = prevCtx.conversation_history || [];

// Check if the owner has already been notified for this lead
const existingStatus = prevCtx.existing_status || '';
const alreadyNotified = existingStatus === 'HOT' ||
                        existingStatus === 'WARM' ||
                        existingStatus === 'COLD' ||
                        existingStatus === 'Manager requested';
history.push({ role: 'assistant', content: cleanResponse });

const allText = history.map(function(m) { return m.content || ''; }).join(' ');
const allTextLower = allText.toLowerCase();

// Name — extracted from the [NAME:] tag Claude sets itself
let detectedName = prevCtx.existing_name || '';
const recordMatch = aiResponse.match(/\[RECORD:\s*name=([^,\]]+)/);
if (recordMatch) detectedName = recordMatch[1].trim();
if (!detectedName) {
  const nameTagMatch = aiResponse.match(/\[NAME:\s*([^\]]+)\]/);
  if (nameTagMatch) detectedName = nameTagMatch[1].trim();
}

// Contact
let detectedContact = '';
const contactMatch = aiResponse.match(/\[RECORD:[^\]]*contact=([^,\]]+)/);
if (contactMatch && contactMatch[1].trim() !== 'none') {
  detectedContact = contactMatch[1].trim();
}
if (!detectedContact) {
  const phoneMatch = allText.match(/(\+[\d\s\-]{9,14}\d)/);
  const emailMatch = allText.match(/[\w.-]+@[\w.-]+\.[a-z]{2,}/i);
  if (phoneMatch) detectedContact = phoneMatch[1].trim();
  else if (emailMatch) detectedContact = emailMatch[0];
}

// Product — only search user messages, not the bot's own messages
let detectedProduct = prevCtx.existing_product || '';
const productMatch = aiResponse.match(/\[UPDATE:[^\]]*product=([^,\]]+)/);
if (productMatch) detectedProduct = productMatch[1].trim();
if (!detectedProduct) {
  const userMessages = history.filter(function(m) { return m.role === 'user'; })
    .map(function(m) { return m.content || ''; }).join(' ').toLowerCase();
  if (userMessages.includes('product 1') || userMessages.includes('sales')) {
    detectedProduct = 'Product 1';
  } else if (userMessages.includes('product 2') || userMessages.includes('support')) {
    detectedProduct = 'Product 2';
  }
}

// Source
let detectedSource = '';
const sourceMatch = aiResponse.match(/\[LEAD_SOURCE:\s*([^\]]+)\]/);
if (sourceMatch) detectedSource = sourceMatch[1].trim();

// Extract call time from user messages
// NOTE: these patterns are examples for English/Russian phrasing —
// add patterns for other languages your customers use.
let detectedCallTime = '';
const userMsgs = history.filter(function(m) { return m.role === 'user'; })
  .map(function(m) { return m.content || ''; }).join(' ');
const timePatterns = [
  /right now(?:[^.!?\n]{0,20})?/i,
  /прямо сейчас(?:[^.!?\n]{0,20})?/i,
  /from\s+\d{1,2}(?::\d{2})?\s*(?:to|-|–)\s*\d{1,2}(?::\d{2})?/i,
  /within\s+(?:the\s+next\s+)?(?:\d+\s+)?hours?/i,
  /tomorrow(?:\s+(?:at\s+)?\d{1,2}(?::\d{2})?)?/i,
  /today(?:\s+(?:at\s+)?\d{1,2}(?::\d{2})?)?/i,
  /\d{1,2}:\d{2}/i,
  /by\s+\d{1,2}(?::\d{2})?/i
];
for (var tp = 0; tp < timePatterns.length; tp++) {
  var tm = userMsgs.match(timePatterns[tp]);
  if (tm) { detectedCallTime = tm[0].trim().substring(0, 30); break; }
}

return [{
  json: {
    channel: prevCtx.channel,
    chat_id: prevCtx.chat_id,
    user_name: prevCtx.user_name,
    username: prevCtx.username,
    timestamp: prevCtx.timestamp,
    clean_response: cleanResponse,
    conversation_history: JSON.stringify(history),
    is_new_lead: prevCtx.is_new_lead,
    lead_status: leadStatus,
    detected_name: detectedName,
    detected_contact: detectedContact,
    detected_product: detectedProduct,
    detected_source: detectedSource,
    has_hot: hasHot,
    has_warm: hasWarm,
    has_cold: hasCold,
    has_manager: hasManager,
    call_time: detectedCallTime,
    notify_owner: (hasHot || hasWarm || hasManager) && detectedContact !== '' && !alreadyNotified
  }
}];
